import { DepositStatusEnum, InvoiceStatusEnum } from '../enums';
import { FatoorahInvoiceItemDto } from './invoice-item.dto';
import { FatoorahInvoiceTransactionModelDto } from './invoice-transaction-model.dto';

export class GetInvoiceStatusResponseDto {
  /**
   * Represents the invoice ID that was used in the inquiry call.
   */
  InvoiceId: number;

  /**
   * The status of the invoice.
   * Possible values: "Pending", "Paid", "Canceled".
   */
  InvoiceStatus: InvoiceStatusEnum;

  /**
   * Invoice reference that is generated by MyFatoorah.
   */
  InvoiceReference: string;

  /**
   * The customer reference data associated with the invoice.
   */
  CustomerReference: string;

  /**
   * The creation date of the invoice.
   * Format: ISO 8601 (e.g., "2025-01-22T10:30:00Z").
   */
  CreatedDate: string;

  /**
   * The expiry date for the invoice.
   * Format: ISO 8601 (e.g., "2025-01-30T23:59:59Z").
   */
  ExpiryDate: string;

  /**
   * The total value of the invoice in the base account currency.
   */
  InvoiceValue: number;

  /**
   * Comments that are associated with the invoice.
   * Primarily used for portal users.
   */
  Comments?: string;

  /**
   * The customer name saved along with the invoice.
   */
  CustomerName: string;

  /**
   * The customer's mobile number.
   */
  CustomerMobile: string;

  /**
   * The customer's email address.
   */
  CustomerEmail: string;

  /**
   * A user-defined field that was stored during the invoice creation.
   */
  UserDefinedField?: string;

  /**
   * The invoice value displayed in case of a different currency from the base one.
   */
  InvoiceDisplayValue: string;

  /**
   * The amount that will be deposited to the vendor.
   */
  DueDeposit: number;

  DepositStatus: DepositStatusEnum;

  InvoiceItems?: FatoorahInvoiceItemDto[];

  InvoiceTransactions: FatoorahInvoiceTransactionModelDto[];
}
